/**
 * SheetJS (xlsx) Library Placeholder
 * 
 * IMPORTANT: Replace this file with the actual SheetJS library for production use.
 * Download from: https://cdn.sheetjs.com/xlsx-latest/package/dist/xlsx.full.min.js
 * 
 * This placeholder provides the minimal API surface used by the SmartExcel application
 * to enable testing and development without the full library.
 */

var XLSX = (function() {
  'use strict';

  /**
   * Read a workbook from binary data.
   * @param {ArrayBuffer|Uint8Array} data - File data
   * @param {Object} opts - Options (e.g., { type: 'array' })
   * @returns {Object} Workbook object
   */
  function read(data, opts) {
    if (!data) throw new Error('No data provided to XLSX.read()');
    
    // Attempt to parse the data as a real workbook
    // This placeholder returns a minimal workbook structure
    var bytes = new Uint8Array(data);
    
    // Check for ZIP signature (PK header) which indicates a real .xlsx file
    var isZip = bytes[0] === 0x50 && bytes[1] === 0x4B;
    // Check for OLE2/BIFF signature which indicates a real .xls file
    var isOLE = bytes[0] === 0xD0 && bytes[1] === 0xCF;
    
    if (!isZip && !isOLE && bytes.length > 0) {
      // Try to interpret as a simple CSV or detect format
      try {
        var text = new TextDecoder().decode(bytes);
        var lines = text.trim().split('\n');
        if (lines.length > 0) {
          var headers = lines[0].split(',').map(function(h) { return h.trim().replace(/^"|"$/g, ''); });
          var rows = [];
          for (var i = 1; i < lines.length; i++) {
            var values = lines[i].split(',').map(function(v) { return v.trim().replace(/^"|"$/g, ''); });
            var row = {};
            headers.forEach(function(header, idx) {
              var val = values[idx] || '';
              // Try to convert numeric strings to numbers
              var num = Number(val);
              row[header] = (val !== '' && !isNaN(num)) ? num : val;
            });
            rows.push(row);
          }
          
          // Build a sheet from parsed CSV
          var sheet = { '!ref': 'A1' };
          sheet['!ref'] = encodeRange(0, 0, lines.length - 1, headers.length - 1);
          
          // Set header cells
          headers.forEach(function(h, c) {
            sheet[encodeCell(0, c)] = { t: 's', v: h };
          });
          
          // Set data cells
          rows.forEach(function(row, r) {
            headers.forEach(function(h, c) {
              var val = row[h];
              if (val !== undefined && val !== null && val !== '') {
                sheet[encodeCell(r + 1, c)] = { 
                  t: typeof val === 'number' ? 'n' : 's', 
                  v: val 
                };
              }
            });
          });
          
          return {
            SheetNames: ['Sheet1'],
            Sheets: { 'Sheet1': sheet }
          };
        }
      } catch(e) {
        // Fall through to error
      }
      throw new Error('Unable to parse file: unrecognized format');
    }
    
    // For real xlsx/xls files, this placeholder cannot parse them
    // Return an empty workbook structure as a fallback
    if (isZip || isOLE) {
      // In production, the real SheetJS library handles this
      // This placeholder signals that real parsing requires the actual library
      throw new Error('Real .xlsx/.xls parsing requires the full SheetJS library. Download from https://cdn.sheetjs.com/xlsx-latest/package/dist/xlsx.full.min.js');
    }
    
    return {
      SheetNames: ['Sheet1'],
      Sheets: { 'Sheet1': { '!ref': 'A1' } }
    };
  }

  function encodeCell(r, c) {
    var col = '';
    var cc = c;
    do {
      col = String.fromCharCode(65 + (cc % 26)) + col;
      cc = Math.floor(cc / 26) - 1;
    } while (cc >= 0);
    return col + (r + 1);
  }

  function encodeRange(r1, c1, r2, c2) {
    return encodeCell(r1, c1) + ':' + encodeCell(r2, c2);
  }

  function decodeCell(cellRef) {
    var match = cellRef.match(/^([A-Z]+)(\d+)$/);
    if (!match) return { r: 0, c: 0 };
    var col = 0;
    for (var i = 0; i < match[1].length; i++) {
      col = col * 26 + (match[1].charCodeAt(i) - 64);
    }
    return { r: parseInt(match[2], 10) - 1, c: col - 1 };
  }

  function decodeRange(rangeStr) {
    if (!rangeStr) return { s: { r: 0, c: 0 }, e: { r: 0, c: 0 } };
    var parts = rangeStr.split(':');
    var s = decodeCell(parts[0]);
    var e = parts.length > 1 ? decodeCell(parts[1]) : s;
    return { s: s, e: e };
  }

  var utils = {
    /**
     * Convert a sheet to an array of JSON objects.
     */
    sheet_to_json: function(sheet, opts) {
      if (!sheet || !sheet['!ref']) return [];
      
      var range = decodeRange(sheet['!ref']);
      var headers = [];
      var data = [];
      var headerRow = (opts && opts.header === 1) ? -1 : 0;
      
      // Read headers from first row
      for (var c = range.s.c; c <= range.e.c; c++) {
        var cell = sheet[encodeCell(range.s.r, c)];
        headers.push(cell ? String(cell.v) : 'Column' + (c + 1));
      }
      
      // Read data rows
      for (var r = range.s.r + 1; r <= range.e.r; r++) {
        var row = {};
        var hasData = false;
        for (var c2 = range.s.c; c2 <= range.e.c; c2++) {
          var cell2 = sheet[encodeCell(r, c2)];
          if (cell2 && cell2.v !== undefined && cell2.v !== null) {
            row[headers[c2 - range.s.c]] = cell2.v;
            hasData = true;
          }
        }
        if (hasData) {
          data.push(row);
        }
      }
      
      return data;
    },

    /**
     * Convert an array of JSON objects to a sheet.
     */
    json_to_sheet: function(data, opts) {
      if (!data || data.length === 0) {
        return { '!ref': 'A1:A1' };
      }
      
      // Get headers from first object keys or opts.header
      var headers = (opts && opts.header) ? opts.header : Object.keys(data[0]);
      var sheet = {};
      
      // Write headers
      headers.forEach(function(h, c) {
        sheet[encodeCell(0, c)] = { t: 's', v: h };
      });
      
      // Write data
      data.forEach(function(row, r) {
        headers.forEach(function(h, c) {
          var val = row[h];
          if (val !== undefined && val !== null) {
            var type = typeof val === 'number' ? 'n' : 's';
            sheet[encodeCell(r + 1, c)] = { t: type, v: val };
          }
        });
      });
      
      sheet['!ref'] = encodeRange(0, 0, data.length, headers.length - 1);
      return sheet;
    },

    /**
     * Create a new empty workbook.
     */
    book_new: function() {
      return { SheetNames: [], Sheets: {} };
    },

    /**
     * Append a sheet to a workbook.
     */
    book_append_sheet: function(wb, sheet, name) {
      var sheetName = name || 'Sheet1';
      wb.SheetNames.push(sheetName);
      wb.Sheets[sheetName] = sheet;
    },

    /**
     * Convert a sheet to CSV string.
     */
    sheet_to_csv: function(sheet, opts) {
      if (!sheet || !sheet['!ref']) return '';
      
      var range = decodeRange(sheet['!ref']);
      var lines = [];
      
      for (var r = range.s.r; r <= range.e.r; r++) {
        var row = [];
        for (var c = range.s.c; c <= range.e.c; c++) {
          var cell = sheet[encodeCell(r, c)];
          var val = cell ? String(cell.v) : '';
          // Escape values containing commas or quotes
          if (val.indexOf(',') >= 0 || val.indexOf('"') >= 0 || val.indexOf('\n') >= 0) {
            val = '"' + val.replace(/"/g, '""') + '"';
          }
          row.push(val);
        }
        lines.push(row.join(','));
      }
      
      return lines.join('\n');
    }
  };

  /**
   * Write a workbook to binary data.
   * @param {Object} wb - Workbook object
   * @param {Object} opts - Options (e.g., { type: 'array', bookType: 'xlsx' })
   * @returns {ArrayBuffer|string} Binary data
   */
  function write(wb, opts) {
    if (!wb) throw new Error('No workbook provided to XLSX.write()');
    
    var bookType = (opts && opts.bookType) || 'xlsx';
    var type = (opts && opts.type) || 'array';
    
    if (bookType === 'csv') {
      var sheetName = wb.SheetNames[0];
      var csv = utils.sheet_to_csv(wb.Sheets[sheetName]);
      if (type === 'array') {
        var encoder = new TextEncoder();
        return encoder.encode(csv).buffer;
      }
      return csv;
    }
    
    // For xlsx format, produce a minimal valid output
    // In production, the real library generates proper ZIP/OOXML
    var sheetName2 = wb.SheetNames[0];
    var sheet = wb.Sheets[sheetName2];
    
    // Serialize the sheet data as CSV in a buffer (simplified xlsx representation)
    var csvContent = utils.sheet_to_csv(sheet);
    var encoder2 = new TextEncoder();
    var encoded = encoder2.encode(csvContent);
    
    if (type === 'array') {
      return encoded.buffer;
    }
    
    return encoded;
  }

  return {
    read: read,
    write: write,
    utils: utils,
    version: 'placeholder-1.0.0'
  };
})();

// Support both browser global and module environments
if (typeof module !== 'undefined' && module.exports) {
  module.exports = XLSX;
}
